//! The idempotent bulk-write algorithm: one `tokio_postgres` transaction per [`ReplayBatch`].
//!
//! Shape (see the task brief for the full rationale):
//! 1. `BEGIN` (via `client.transaction()`).
//! 2. Create six `TEMP … ON COMMIT DROP` staging tables with plain column types (enum/`Age`
//!    columns as `TEXT`; no `elo_bucket` column on the players staging — it is generated by the
//!    DB).
//! 3. Binary `COPY IN` each `Vec<DTO>` into its staging table.
//! 4. Insert matches, capturing only genuinely-new ids in a `new_match_ids` TEMP table, then gate
//!    every child insert on a `JOIN … USING (match_id)` against it — re-ingesting an
//!    already-seen batch inserts zero rows anywhere.
//! 5. `COMMIT` and return the row counts.
//!
//! A DB error at any step (e.g. a FK violation on `map_id`/`civ_id`) propagates as `Err` and the
//! transaction rolls back on drop — nothing partial is ever committed.

use anyhow::{Context, Result};
use tokio_postgres::binary_copy::BinaryCopyInWriter;
use tokio_postgres::types::{ToSql, Type};
use tokio_postgres::{Client, Transaction};

use crate::dto::{
    IngestStats, NewMatch, NewMatchPlayer, NewMatchPlayerTech, NewMatchPlayerUnit, NewReplayAge,
    NewReplayEvent, ReplayBatch,
};

/// One staging table's COPY column list: `(column name, wire type)` pairs in the exact COPY
/// order. Declaring this ONCE per table — instead of hand-syncing the `COPY` SQL string, the
/// `[Type; N]` array, and the per-row `[&dyn ToSql; N]` params independently — means the SQL
/// column list and the `Type` list can never drift apart. The per-row params array below still
/// has to be written in the same order by hand (there is no reflection from a `(&str, Type)` pair
/// to "the struct field with that name"), so it remains the one place a future column addition
/// must also touch — but that is now a 2-way, not 3-way, sync.
struct TableColumns {
    staging_table: &'static str,
    columns: &'static [(&'static str, Type)],
}

impl TableColumns {
    /// `COPY <staging_table> (<col, col, ...>) FROM STDIN BINARY`, built from `columns` so the
    /// column list is always in the same order as [`Self::types`].
    fn copy_sql(&self) -> String {
        let names: Vec<&str> = self.columns.iter().map(|(name, _)| *name).collect();
        format!(
            "COPY {} ({}) FROM STDIN BINARY",
            self.staging_table,
            names.join(", ")
        )
    }

    /// The wire `Type` list, in the same order as [`Self::copy_sql`]'s column list.
    fn types(&self) -> Vec<Type> {
        self.columns.iter().map(|(_, ty)| ty.clone()).collect()
    }
}

